	(3, '6a88fc6b-3536-4c6d-a334-240a70c8bf64', 'Tính điểm hệ 4', 'Trên Portal hiện điểm GPA hệ 4 là 2.8 nhưng trên này chỉ hiện 2.7 dù em đã nhập đúng hết các điểm và các môn có tính GPA hay không. Điểm hệ 10 thì đúng nhưng hệ 4 bị lệch 0.1 điểm', 'ok', '2026-03-12 03:25:35.138848+00'),
	(4, NULL, 'Tính điểm hệ 4', 'trên HUB Portal của em là 3.4 mà trong này tính ra còn có 3.3 thui ạ', 'ok', '2026-03-14 03:46:39.797784+00'),
	(7, '839387a0-1e34-41d2-a83b-acd3ae26e5d3', 'không hiện bảng điểm', 'hệ thống thông báo bảng điểm sai định dạng gì đó rồi không hiện những môn mình đã nhập', 'ok', '2026-03-17 03:44:48.972944+00'),
	(9, '43ea70cc-3545-430c-af05-2b17edbc6f47', 'tính điểm hệ 4 và số tín chỉ', 'em nhập điểm bằng việc xuất file pdf bên hub portal qua nhưng hai bên cho ra số điểm và số tín chỉ tích lũy khác nhau ạ', 'ok', '2026-03-18 15:23:59.269496+00'),
