INSERT INTO "public"."feedback" ("id", "created_at", "type", "content", "contact", "status", "user_id") VALUES
	(9, '2026-03-01 14:34:06.777115+00', 'idea', 'Thật sự cảm ơn admin đã tạo ra web trên, từ khi có công cụ này em cảm thấy mình làm chủ thời các môn học hơn trên giảng đường. Có một góp ý nhỏ là admin có thể lưu dữ liệu các thành tích của các kì trước khi minh add file fpd của kì này được không ạ, em nghĩ rằng với tính năng trên sẽ giúp sinh viên theo dõi được quá trình phấn đấu học tập của bản thân', '', 'ok', NULL),
	(5, '2026-02-24 17:52:39.245447+00', 'bug', 'Xe buýt 104 không chạy tới trường nữa. Từ 1/8/2025 là chỉ tới Văn Thánh ( Bình Thạnh) ah', '0399004436', 'ok', NULL),
	(3, '2026-02-02 04:58:54.950312+00', 'idea', 'Có thể thêm tính nắng đánh dấu lại các môn bị nợ/rớt môn không an?', '', 'ok', NULL),
	(4, '2026-02-24 17:50:44.235363+00', 'bug', 'Thiếu ENL701_252_1_D27. Tiếng Anh chuyên ngành 1.Thứ Năm,7H00 - 11h05,A305,56 Hoàng Diệu 2 - Thủ Đức.Từ Văn Năm. Cảm ơn web nhiều lắm. quá xịn luôn', '0399004436', 'ok', NULL),
	(2, '2026-01-31 10:18:38.195192+00', 'idea', 'Dạ mục Sự kiện ĐRL, có thể cập nhật tính năng đánh dấu "Đã tham dự/Chưa tham dự" cho dễ theo dõi được không ạ?', '', 'ok', NULL),
	(10, '2026-03-26 08:05:07.246785+00', 'idea', 'có thể thêm tính năng theo dõi hoặc liên quan tới các môn học cải thiện hoặc học lại không ạ?', '', 'ok', NULL),
	(12, '2026-04-04 08:05:13.111846+00', 'idea', 'Dạ  em hi vong bên mình có thể phát triển thêm mục các môn học mở trong học kì hè. Mục đích là giúp các bạn sinh viên HUB có thể nắm rõ, tự lập kế hoạch học tập và không bị động khi muốn đẩy nhanh tiến độ ra trường.', '', 'ok', NULL),
	(13, '2026-04-07 14:51:14.56861+00', 'idea', 'Chưa có hệ QTSB ạaa', '120107250012@st.buh.edu.vn', 'new', NULL),
	(11, '2026-03-30 14:39:19.599451+00', 'bug', 'g', '', 'ok', NULL);
